"use client";
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

import { AiOutlineEye, AiOutlineEyeInvisible } from "react-icons/ai"; // 👈 React Icons

export default function SignupPage() {
  const [step, setStep] = useState<"choose" | "signup" | "admin">("choose");
  const [role, setRole] = useState<"user" | "vendor" | null>(null);
  const [form, setForm] = useState({ name: "", email: "", password: "" });
  const [showPassword, setShowPassword] = useState(false); // 👁️ Toggle state

  async function handleSignup(e: React.FormEvent) {
    e.preventDefault();
    alert("kya be bana toh le signUp api")
  }

  async function handleAdminLogin(e: React.FormEvent) {
    e.preventDefault();
    alert("kya be bana toh le admin login api");
  }

  // 👇 Google signup handler
  const handleGoogleSignup = async () => {
    alert("Goggle se login karega munna")
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-900 via-black to-gray-800 text-white p-6">
      <AnimatePresence mode="wait">
        {step === "choose" && (
          <motion.div
            key="choose"
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -40 }}
            transition={{ duration: 0.5 }}
            className="w-full max-w-md bg-white/10 backdrop-blur-md rounded-2xl shadow-2xl p-8 border border-white/20"
          >
            <h1 className="text-3xl font-semibold text-center mb-8">
              Welcome to <span className="text-blue-400">MultiCart</span>
            </h1>
            <div className="flex flex-col gap-4">
              <button
                onClick={() => {
                  setRole("user");
                  setStep("signup");
                }}
                className="bg-gradient-to-r from-blue-500 to-blue-700 py-3 rounded-xl font-medium hover:opacity-90 transition"
              >
                🛍️ User Sign Up
              </button>

              <button
                onClick={() => {
                  setRole("vendor");
                  setStep("signup");
                }}
                className="bg-gradient-to-r from-green-500 to-emerald-700 py-3 rounded-xl font-medium hover:opacity-90 transition"
              >
                🏪 Create Your Shop
              </button>

              <button
                onClick={() => setStep("admin")}
                className="bg-gradient-to-r from-yellow-500 to-amber-700 py-3 rounded-xl font-medium hover:opacity-90 transition"
              >
                🧑‍💼 Login as Admin
              </button>
            </div>
          </motion.div>
        )}

        {step === "signup" && (
          <motion.div
            key="signup"
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -40 }}
            transition={{ duration: 0.5 }}
            className="w-full max-w-md bg-white/10 backdrop-blur-md rounded-2xl shadow-2xl p-8 border border-white/20"
          >
            <h2 className="text-2xl font-semibold text-center mb-6">
              {role === "vendor" ? "Create Your Shop" : "User Registration"}
            </h2>
            <form onSubmit={handleSignup} className="flex flex-col gap-4">
              {/* Name */}
              <input
                type="text"
                placeholder="Full Name"
                required
                className="bg-white/10 border border-white/30 rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
                onChange={(e) => setForm({ ...form, name: e.target.value })}
              />
              {/* Email */}
              <input
                type="email"
                placeholder="Email Address"
                required
                className="bg-white/10 border border-white/30 rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-blue-500"
                onChange={(e) => setForm({ ...form, email: e.target.value })}
              />

              {/* Password with Eye Toggle */}
              <div className="relative">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Password"
                  required
                  className="w-full bg-white/10 border border-white/30 rounded-lg p-3 pr-10 focus:outline-none focus:ring-2 focus:ring-blue-500"
                  onChange={(e) => setForm({ ...form, password: e.target.value })}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-white transition"
                >
                  {showPassword ? <AiOutlineEyeInvisible size={22} /> : <AiOutlineEye size={22} />}
                </button>
              </div>

              {/* Signup Button */}
              <button
                type="submit"
                className="bg-gradient-to-r from-blue-500 to-blue-700 py-3 rounded-xl font-medium hover:opacity-90 transition"
              >
                {role === "vendor" ? "Register Shop" : "Create Account"}
              </button>

              {/* Divider */}
              <div className="flex items-center my-3">
                <div className="flex-1 h-px bg-gray-600"></div>
                <span className="px-3 text-sm text-gray-400">or</span>
                <div className="flex-1 h-px bg-gray-600"></div>
              </div>

              {/* Google Signup Button */}
              <motion.button
                type="button"
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.97 }}
                onClick={handleGoogleSignup}
                className="flex items-center justify-center gap-3 py-3 bg-white/10 hover:bg-white/20 border border-white/30 rounded-xl transition"
              >
                <img
                  src="https://www.svgrepo.com/show/475656/google-color.svg"
                  alt="Google"
                  className="w-5 h-5"
                />
                <span className="font-medium">Register with Google</span>
              </motion.button>

              <p
                onClick={() => setStep("choose")}
                className="text-center text-sm mt-4 text-gray-300 hover:text-white cursor-pointer"
              >
                ⬅ Back to selection
              </p>
            </form>
          </motion.div>
        )}

        {step === "admin" && (
          <motion.div
            key="admin"
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -40 }}
            transition={{ duration: 0.5 }}
            className="w-full max-w-md bg-white/10 backdrop-blur-md rounded-2xl shadow-2xl p-8 border border-white/20"
          >
            <h2 className="text-2xl font-semibold text-center mb-6">Admin Login</h2>
            <form onSubmit={handleAdminLogin} className="flex flex-col gap-4">
              <input
                type="email"
                placeholder="Admin Email"
                required
                className="bg-white/10 border border-white/30 rounded-lg p-3 focus:outline-none focus:ring-2 focus:ring-amber-500"
                onChange={(e) => setForm({ ...form, email: e.target.value })}
              />
              <div className="relative">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Admin Password"
                  required
                  className="w-full bg-white/10 border border-white/30 rounded-lg p-3 pr-10 focus:outline-none focus:ring-2 focus:ring-amber-500"
                  onChange={(e) => setForm({ ...form, password: e.target.value })}
                />
                <button
                  type="button"
                  onClick={() => setShowPassword(!showPassword)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-white transition"
                >
                  {showPassword ? <AiOutlineEyeInvisible size={22} /> : <AiOutlineEye size={22} />}
                </button>
              </div>

              <button
                type="submit"
                className="bg-gradient-to-r from-yellow-500 to-amber-700 py-3 rounded-xl font-medium hover:opacity-90 transition"
              >
                Login as Admin
              </button>

              <p
                onClick={() => setStep("choose")}
                className="text-center text-sm mt-4 text-gray-300 hover:text-white cursor-pointer"
              >
                ⬅ Back to selection
              </p>
            </form>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
